update lessons set objective_ar='أقرأ نص «طائر القطا» المعلوماتي، وأحدّد فكرته الرئيسة وأفكاره الفرعية بتحليل المعلومات الصريحة والضمنية، وأقارن بين أنواع القطا، وأستنتج أهمية حمايته من الانقراض.' where code='AR-Y7-N-T2-L06';
update success_criteria set statement_ar='أحدّد الفكرة الرئيسة والأفكار الفرعية، وأستخرج معلومات صريحة عن القطا.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L06');
update success_criteria set statement_ar='أستنتج معلومات ضمنية، وأقارن بين أنواع القطا بأدلة من النص.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L06');
update success_criteria set statement_ar='أقيّم أسباب تناقص القطا، وأقترح حلولًا لحمايته مدعومة بالأدلة.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L06');
update lesson_summaries set content=content||'{"hook": "كيف يسقي طائر القطا فراخه؟ ماذا تعرف عن طيور صحراء الإمارات؟", "idea": "نص معلوماتي يعرض خصائص طائر القطا وطريقته في سقي فراخه وأنواعه في دولة الإمارات، وذكره في الشعر العربي، وتناقص أعداده بسبب الصيد الجائر.", "learn": [["📖", "أقرأ النص في كتابي ص 79–82."], ["🎯", "أحدّد الفكرة الرئيسة والأفكار الفرعية."], ["🧩", "ما أعرفه ← ما أريد معرفته ← ما تعلّمته."], ["🔎", "أقارن بين أنواع القطا بأدلة من النص."], ["💡", "أقترح حلولًا لحماية القطا من الانقراض."]], "do": ["١) أعد قراءة النص واكتب ثلاث أفكار رئيسة.", "٢) صمّم ملصقًا قصيرًا لحماية طائر القطا."], "quiz": [["بحسّه المذهل وسرعة انتباهه.", true], ["بكثرته في المدن.", false]], "words": [["يَجْثُم", "يلزم مكانه أو يلتصق بالأرض"], ["الغَسَق", "ظلمة أول الليل"], ["مَلاذَه", "ملجأه"], ["الجائِر", "الظالم المتجاوز للحدّ"], ["مَهارَة", "جدول التعلّم الذاتي"]], "think": "كيف أستنتج المعلومات الضمنية في نص معلوماتي جديد؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L06');update lessons set objective_ar='أبيّن المعنى الإجمالي لقصيدة «رسالة إلى أمي» لنزار قباني، وأحلّل العاطفة والنبرة والصور، وأحدّد الأغراض البلاغية للأساليب الإنشائية، وأكتب رسالة وجدانية قصيرة.' where code='AR-Y7-N-T2-L18';
update success_criteria set statement_ar='أحدّد الفكر الرئيسة والعاطفة والنبرة والمعنى الإجمالي.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L18');
update success_criteria set statement_ar='أحلّل الأغراض البلاغية للنداء والاستفهام والدعاء، وأفسّر الصور.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L18');
update success_criteria set statement_ar='أكتب رسالة وجدانية قصيرة توظّف الأساليب الإنشائية، وأقيّمها بمعيار.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L18');
update lesson_summaries set content=content||'{"hook": "ماذا تكتب في رسالة إلى أمك وأنت بعيد عنها؟ ما الكلمة التي لم تقلها لأمك بعد؟", "idea": "قصيدة وجدانية لنزار قباني، يخاطب فيها أمه بعد عامين من الغربة، فيحنّ إلى حنانها وإلى أبيه وبيته الكبير وطفولته ودمشق.", "learn": [["📖", "أقرأ القصيدة في كتابي ص 186–187."], ["🎯", "أحدّد العاطفة والنبرة والمعنى الإجمالي."], ["🧩", "«أيا أمي» نداء · «وأين طفولتي؟» استفهام · «سقى الرحمن مثواه» دعاء."], ["🔎", "الحنين إلى الأم يتّصل بالحنين إلى الوطن."], ["💡", "أكتب رسالة وجدانية إلى أمي."]], "quiz": [["التحسّر والشوق.", true], ["طلب معلومة.", false]], "words": [["الحَنين", "الشوق إلى من نحب"], ["أَبْحَرْ", "سافر في البحر"], ["تَنْشُلُني", "تنقذني وترفعني"], ["مَثْواه", "قبره ومكان إقامته"], ["مَهارَة", "الأساليب الإنشائية وأغراضها"]]}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L18');update lessons set objective_ar='أقرأ قصيدة «ثوب العيد» لمحمد ذيب النطافي، وأحدّد فكرها وعاطفة الأب فيها، وأفسّر صورها ودلالات ألفاظها، وأعلّل أثر التكرار في إيصال العاطفة.' where code='AR-Y7-N-T2-L19';
update success_criteria set statement_ar='أحدّد الفكرة العامة والفكر الجزئية، ونوع العاطفة في القصيدة.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L19');
update success_criteria set statement_ar='أفسّر الصور الفنية ودلالات الألفاظ، وأعلّل أثر التكرار في إبراز العاطفة.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L19');
update success_criteria set statement_ar='أوازن بين فرح الأب بالعيد ونظرة شاعر آخر إلى العيد، وأكتب مقطعًا عن فرحة أسرتي.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L19');
update lesson_summaries set content=content||'{"emoji": "🌙", "hook": "لماذا يفرح الأب بالعيد كما يفرح ابنه؟ متى شعرت أن فرحة والديك من فرحتك؟", "idea": "قصيدة يوقظ فيها الأب ابنه صباح العيد، ويعبّر عن فرحه الغامر بفرحة ابنه، حتى كأنه عاد طفلًا من جديد.", "learn": [["📖", "أقرأ القصيدة في كتابي ص 193–194."], ["🎯", "أحدّد الفكرة والعاطفة في النص الشعري."], ["🧩", "أجمع ألفاظ الشعور ← أحدّد نوع العاطفة ← أربطها بالفكرة."], ["🔎", "التكرار يؤكّد فرح الأب ويقرّب صوته من الطفل."], ["💡", "أكتب مقطعًا عن فرحة أسرتي بالعيد."]], "do": ["١) احفظ ستة أسطر من القصيدة، واكتب ثلاث أفكار رئيسة.", "٢) اكتب مثالًا آخر للتكرار في القصيدة وبيّن أثره."], "quiz": [["فرح الأب وحبّه لابنه.", true], ["الحزن والحنين.", false]], "words": [["الرَّوابي", "التلال المرتفعة"], ["هامَتْ", "تجوّلت وأحبّت"], ["الهَنا", "السعادة"], ["النَّضير", "الأخضر الحسن"], ["مَهارَة", "تحديد العاطفة في النص الشعري"]], "think": "كيف أحدّد العاطفة في قصيدة جديدة؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L19');update lessons set objective_ar='أحلّل قصة «قلب أمي» لنايف النوايسة إلى عناصرها الفنية، وأتتبّع أحداثها بين السرد والوصف والحوار، وأعلّل استخدام اللغة المجازية، وأستنتج قيم البرّ والإحسان فيها.' where code='AR-Y7-N-T2-L20';
update success_criteria set statement_ar='أحدّد عناصر القصة وأرتّب أحداثها، وأميّز السرد من الوصف والحوار.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L20');
update success_criteria set statement_ar='أعلّل استخدام اللغة المجازية وأثرها، وأفسّر ربط العنوان بقلب الأم.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L20');
update success_criteria set statement_ar='أقيّم موقف الابن من السائق، وأقارن القصة بقصيدة «خمس رسائل إلى أمي» في الأسلوب.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L20');
update lesson_summaries set content=content||'{"hook": "ماذا تفعل لو رفض أحدٌ مساعدتك ثم احتاج إليك؟ هل نردّ الإساءة بالإحسان؟", "idea": "قصة ابن بارّ يحمل أمه المريضة ليلًا إلى المستشفى، فيسخر منه سائق ويتركه، ثم يصل فيجد السائق مصابًا فيتبرّع له بدمه وينقذ حياته.", "learn": [["📖", "أقرأ القصة في كتابي ص 202–206."], ["🎯", "أتتبّع الأحداث بين السرد والوصف والحوار."], ["🧩", "أحدّد الحدث ← طريقة تقديمه ← أعلّل اختيار الكاتب."], ["🔎", "«أرقام السيارات تهزأ مني»: تشخيص يصوّر وحدة الابن."], ["💡", "أردّ الإساءة بالإحسان، وأبرّ والديّ."]], "do": ["١) أعد قراءة القصة واكتب ثلاث أفكار رئيسة.", "٢) اكتب موقفًا قابلت فيه إساءة بإحسان، بالسرد والحوار."], "quiz": [["لأنه لا يحب أن يُعذَّب الآخرون بالخير.", true], ["لأنه ندم على التبرّع.", false]], "words": [["الواهِنَة", "الضعيفة"], ["هَواجِس", "ما يخطر في النفس من قلق"], ["أَسْتَجْلِيَ", "أكشف وأتبيّن"], ["تُحَوْقِلُ", "تقول: لا حول ولا قوة إلا بالله"], ["مَهارَة", "التركيز على الأحداث"]], "think": "كيف أميّز السرد من الوصف والحوار في قصة جديدة؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L20');update lessons set objective_ar='أحدّد الفكرة المحورية في نص «مع والديّ» وارتباط أفكاره الرئيسة، وأجمّع مفهومه المفتاحي (انتقال المسؤولية)، وأحلّل أسلوب الكاتب في الشرح والإقناع بالمثال، وأقترح سلوكيات تبني ثقة والديّ بي.' where code='AR-Y7-N-T2-L21';
update success_criteria set statement_ar='أحدّد الفكرة المحورية والفكر الداعمة، وأستدلّ على ارتباطها.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L21');
update success_criteria set statement_ar='أفسّر مثل الحبل بين السفينتين، وأحلّل أسلوب الكاتب في الشرح والإقناع.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L21');
update success_criteria set statement_ar='أقيّم رأي الكاتب في التدرّج، وأصمّم خطة أعمال تبني ثقة والديّ بي.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L21');
update lesson_summaries set content=content||'{"emoji": "⛵", "hook": "ما المسؤولية التي أوكلها إليك والداك هذا العام؟ هل تريد الحرية كلها دفعة واحدة؟", "idea": "نص معلوماتي للدكتور هارولد شرايوك يبيّن أن المراهقة فترة تدريب تنتقل فيها المسؤولية من الوالدين إلى الابن بالتدريج، كما ينتقل الحبل من سفينة إلى أخرى، وأن بناء الثقة بالأعمال طريق إلى الشخصية المتكاملة.", "learn": [["📖", "أقرأ النص في كتابي ص 213–214."], ["🎯", "أحدّد الفكرة المحورية وأربط بها الفكر الداعمة."], ["🧩", "الفكرة ← المثال ← التحذير ← الحلّ."], ["🔎", "مثل الحبل بين السفينتين يشرح انتقال المسؤولية."], ["💡", "أبني ثقة والديّ بأعمال مسؤولة."]], "do": ["١) أعد قراءة النص واكتب ثلاث أفكار رئيسة.", "٢) اكتب ثلاثة أعمال تبني ثقة والديك بك هذا الأسبوع."], "quiz": [["انتقال المسؤولية من الوالدين إلى الابن.", true], ["قوة البحّارة.", false]], "words": [["أَطْوارِك", "مراحلك، مفردها طَوْر"], ["تَتوقُ", "تشتاق وتتطلّع"], ["اضْطِراب", "خلل وعدم انتظام"], ["تُرَسِّخُ", "تثبّت وتقوّي"], ["مَهارَة", "ارتباط الأفكار وأسلوب الكاتب"]], "think": "كيف أكتشف ارتباط الأفكار في نص معلوماتي جديد؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L21');update lessons set objective_ar='أقرأ نص «العطف على الأبناء» قراءة واعية، وأجمّع مفهومه المفتاحي (غريزة الأمومة)، وأربط أفكاره الرئيسة بأمثلته وحقائقه، وأحلّل أسلوب الكاتب في الشرح والإقناع.' where code='AR-Y7-N-T2-L22';
update success_criteria set statement_ar='أحدّد الفكرة الرئيسة لكل فقرة، والمثال أو الحقيقة التي تدعمها.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L22');
update success_criteria set statement_ar='أجمّع المفهوم المفتاحي، وأفسّر ترابط الأفكار وأسلوب الكاتب في الشرح والإقناع.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L22');
update success_criteria set statement_ar='أقيّم قوة الأدلة في النص، وأضيف مثالًا جديدًا موثّقًا عن عاطفة الحيوانات.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T2-L22');
update lesson_summaries set content=content||'{"emoji": "🐘", "hook": "ما الذي يدفع الأم في عالم الحيوان إلى التضحية بنفسها؟ اذكر حيوانًا رأيته يحمي صغاره.", "idea": "نص معلوماتي يبيّن أن غريزة الأمومة التي وهبها الله للحيوانات تدفعها إلى حماية صغارها، ويدعم ذلك بأمثلة: الفيل وفرس البحر والحوت والدب الأبيض والسلاحف والتماسيح.", "learn": [["📖", "أقرأ النص في كتابي ص 221–222."], ["🎯", "أجمّع المفهوم المفتاحي: غريزة الأمومة."], ["🧩", "أقرأ الفقرة ← أحدّد فكرتها ← أستخرج المثال والحقيقة ← أربطها بالمفهوم."], ["🔎", "الكاتب يشرح بالأمثلة ليقنع القارئ بفكرته."], ["💡", "أطبّق المهارة على نص معلوماتي جديد."]], "do": ["١) أعد قراءة النص واكتب ثلاث أفكار رئيسة.", "٢) اكتب فقرة عن حيوان آخر يحمي صغاره، مع حقيقة تدعمها."], "quiz": [["إقناع القارئ بأن لدى الحيوانات عاطفة الأمومة.", true], ["تعداد صفات الحيوانات.", false]], "words": [["الغَرائِز", "طباع فطرية يولد بها الكائن"], ["آخِرِ رَمَقٍ", "آخر ما بقي من الحياة"], ["لا تَنْفَكُّ", "لا تتوقّف"], ["تُضَلِّلَ", "تخدع وتوهم"], ["مَهارَة", "تجميع المفهوم المفتاحي"]], "think": "كيف أجمّع المفهوم المفتاحي في نص معلوماتي جديد؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T2-L22');update lessons set objective_ar='أصنّف النصوص وفق القالب (مطبوع أو إلكتروني) ووفق التنسيق (ممتد، غير ممتد، مركّب، متعدّد)، وأحلّل نماذج منها مثل «الأبنية صديقة البيئة»، وأختار التنسيق المناسب لغرضي.' where code='AR-Y7-N-T3-L01';
update success_criteria set statement_ar='أحدّد قالب النص وتنسيقه، وأذكر أمثلة لكل تنسيق.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y7-N-T3-L01');
update success_criteria set statement_ar='أعلّل تصنيف نص ما بخصائصه، وأوازن بين النص الممتد وغير الممتد والمركّب.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y7-N-T3-L01');
update success_criteria set statement_ar='أحوّل نصًّا ممتدًّا إلى نص غير ممتد أو مركّب، وأقيّم أيّهما أوضح للقارئ.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y7-N-T3-L01');
update lesson_summaries set content=content||'{"hook": "بريد إلكتروني، وجدول مواعيد، ومقالة مصوّرة: بماذا يختلف كل نص منها في شكله؟", "idea": "درس يصنّف النصوص وفق القالب (مطبوع ورقي أو إلكتروني) ووفق التنسيق (ممتد، وغير ممتد، ومركّب، ومتعدّد)، مع نماذج مثل «الأبنية صديقة البيئة».", "learn": [["📖", "أقرأ الدرس في كتابي ص 8–16."], ["🎯", "أصنّف النص وفق القالب والتنسيق."], ["🧩", "فقرات مترابطة؟ جداول ورسوم؟ أكثر من مصدر؟ ← أحدّد التنسيق."], ["🔎", "«الأبنية صديقة البيئة» نص ممتد."], ["💡", "أختار التنسيق المناسب لغرضي."]], "do": ["١) اجمع ثلاثة نصوص من حياتك اليومية وصنّفها وفق القالب والتنسيق.", "٢) حوّل فقرة ممتدة إلى جدول أو مخطط."], "quiz": [["نص غير ممتد.", true], ["نص ممتد.", false]], "words": [["القالَب", "الشكل الذي يظهر فيه النص للقارئ"], ["الجَزيرَة الحَرارِيَّة", "تركيز الحرارة في المناطق المزدحمة"], ["اسْتِنْزاف", "استهلاك حتى النفاد"], ["المُسْتَدامَة", "التي تحفظ الموارد للأجيال القادمة"], ["مَهارَة", "التصنيف وفق القالب والتنسيق"]], "think": "كيف أختار التنسيق المناسب لنص أكتبه؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y7-N-T3-L01');